%,#eef0f5 75%),linear-gradient(-45deg,transparent 75%,#eef0f5 75%);background-size:22px 22px;background-position:0 0,0 11px,11px -11px,-11px 0}.preview-box img{display:block;max-width:100%;max-height:360px;object-fit:contain}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:13px}.stat{padding:12px;text-align:center;background:var(--soft);border-radius:11px}.stat strong{display:block;font-size:13px;color:var(--brand)}.stat span{font-size:10px;color:var(--muted)}.result-actions{justify-content:center}.info-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}.info{background:#fff;border:1px solid var(--line);border-radius:15px;padding:18px}.info-icon{font-size:20px}.info h3{margin:9px 0 5px;font-size:14px}.info p{margin:0;color:var(--muted);font-size:12px;line-height:1.6}.content{margin-top:18px;background:#fff;border:1px solid var(--line);border-radius:18px;padding:24px}.content h2{margin:0 0 8px;font-size:20px}.content p,.content li{color:var(--muted);font-size:13px;line-height:1.75}.content ol{padding-left:20px;margin-bottom:0}@media(max-width:700px){.compressor-page{width:calc(100% - 16px)}.tool-card{padding:14px}.drop-zone{min-height:230px}.previews,.info-grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr 1fr}.file-row{align-items:flex-start;flex-direction:column;gap:4px}.hero h1{letter-spacing:-1.2px}}
